//! Domain types, one module per group of `docs/ANA-9.md` §5 tables.
//!
//! Field names are §5 column names verbatim and enum variant orders are the `CHECK (... IN ...)`
//! orders (plan D3, blueprint B.1/B.3). Every struct derives `Debug, Clone, PartialEq, Serialize,
//! Deserialize`; every enum adds `Copy, Eq, Hash` and is generated by `str_enum!`, so `as_str`
//! and the serde representation can never disagree.

/// Failure of [`core::str::FromStr`] for a database-text enum.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("`{value}` is not a valid {enum_name}")]
pub struct ParseEnumError {
    /// Name of the Rust enum that rejected the value, e.g. `"Status"`.
    pub enum_name: &'static str,
    /// The text that did not match any variant.
    pub value: String,
}

/// Declares a `TEXT NOT NULL CHECK (... IN ...)` column as a Rust enum.
///
/// Generates `ALL` (variants in `CHECK` order), `as_str`, [`core::fmt::Display`],
/// [`core::str::FromStr`] with [`ParseEnumError`], and serde renames driven by the same string
/// literal, so the database text has exactly one definition per variant.
// Textually scoped: every `mod` below is declared after this definition, so the macro is in
// scope in each of them without an import.
macro_rules! str_enum {
    (
        $(#[$enum_meta:meta])*
        $name:ident {
            $( $(#[$variant_meta:meta])* $variant:ident => $text:literal ),+ $(,)?
        }
    ) => {
        $(#[$enum_meta])*
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, serde::Serialize, serde::Deserialize)]
        #[cfg_attr(feature = "sqlx", derive(sqlx::Type))]
        #[cfg_attr(feature = "sqlx", sqlx(type_name = "text"))]
        pub enum $name {
            $(
                $(#[$variant_meta])*
                #[serde(rename = $text)]
                #[cfg_attr(feature = "sqlx", sqlx(rename = $text))]
                $variant,
            )+
        }

        impl $name {
            #[doc = concat!("Every `", stringify!($name), "` variant, in DDL `CHECK` order.")]
            pub const ALL: &'static [Self] = &[$(Self::$variant),+];

            #[doc = concat!("The database text of this `", stringify!($name), "`.")]
            #[must_use]
            pub const fn as_str(self) -> &'static str {
                match self {
                    $(Self::$variant => $text,)+
                }
            }
        }

        impl ::core::fmt::Display for $name {
            fn fmt(&self, f: &mut ::core::fmt::Formatter<'_>) -> ::core::fmt::Result {
                f.write_str(self.as_str())
            }
        }

        impl ::core::str::FromStr for $name {
            type Err = $crate::model::ParseEnumError;

            fn from_str(s: &str) -> ::core::result::Result<Self, Self::Err> {
                match s {
                    $($text => Ok(Self::$variant),)+
                    other => Err($crate::model::ParseEnumError {
                        enum_name: stringify!($name),
                        value: other.to_owned(),
                    }),
                }
            }
        }
    };
}

