#[cfg(test)]
mod tests {
    use super::*;
    use core::fmt::{Debug, Display};
    use core::str::FromStr;
    use serde::Serialize;
    use serde::de::DeserializeOwned;
    use uuid::Uuid;

    /// Asserts that `ALL` matches the DDL `CHECK` list exactly (same values, same order) and that
    /// every variant round-trips through `as_str` / `FromStr` / serde.
    fn check_enum<T>(all: &[T], texts: &[&str])
    where
        T: Copy + Debug + PartialEq + Display + FromStr + Serialize + DeserializeOwned,
        <T as FromStr>::Err: Debug,
    {
        assert_eq!(
            all.len(),
            texts.len(),
            "variant count differs from the CHECK list"
        );
        for (variant, text) in all.iter().zip(texts) {
            assert_eq!(&variant.to_string(), text, "as_str / CHECK order mismatch");
            let parsed = T::from_str(text).expect("CHECK text parses");
            assert_eq!(&parsed, variant, "FromStr round-trip");
            let json = serde_json::to_string(variant).expect("serialize");
            assert_eq!(json, format!("\"{text}\""), "serde rename follows as_str");
            let back: T = serde_json::from_str(&json).expect("deserialize");
            assert_eq!(&back, variant, "serde round-trip");
        }
    }

    #[test]
    fn status_matches_check_list() {
        check_enum(
            Status::ALL,
            &[
                "open",
                "queued",
                "in_progress",
                "awaiting_approval",
                "blocked",
                "done",
                "failed",
                "closed",
            ],
        );
    }

    #[test]
    fn link_kind_matches_check_list() {
        check_enum(
            LinkKind::ALL,
            &["blocked_by", "origin", "relates", "supersedes"],
        );
    }

    #[test]
    fn run_enums_match_check_lists() {
        check_enum(RunKind::ALL, &["graph", "chat"]);
        check_enum(RunMode::ALL, &["manual", "auto"]);
        check_enum(
            RunStatus::ALL,
            &[
                "queued",
                "running",
                "awaiting_approval",
                "done",
                "failed",
                "cancelled",
            ],
        );
        check_enum(
            StepStatus::ALL,
            &[
                "pending",
                "running",
                "awaiting_approval",
                "done",
                "failed",
                "cancelled",
                "superseded",
            ],
        );
        check_enum(
            GateOutcome::ALL,
            &["approved", "rejected", "retried", "skipped"],
        );
        check_enum(VerifyOutcome::ALL, &["pass", "fail", "unavailable"]);
        check_enum(
            CommandRunStatus::ALL,
            &["queued", "running", "done", "failed", "cancelled"],
        );
    }

    #[test]
    fn event_enums_match_check_lists() {
        check_enum(
            EventKind::ALL,
            &[
                "prompt",
                "follow_up",
                "assistant_text",
                "thought",
                "tool_call",
                "tool_result",
                "edit_proposal",
                "permission_request",
                "permission_answer",
                "plan",
                "usage",
                "error",
                "done",
                "other",
            ],
        );
        check_enum(EventRole::ALL, &["user", "agent", "htui"]);
    }

    #[test]
    fn box_and_agent_enums_match_check_lists() {
        check_enum(OsFamily::ALL, &["windows", "linux", "macos"]);
        check_enum(Transport::ALL, &["acp", "cli"]);
        check_enum(Billing::ALL, &["subscription", "per_token"]);
    }

    #[test]
    fn phase_enums_match_check_lists() {
        check_enum(Gate::ALL, &["always", "on_failure", "never"]);
        check_enum(
            Isolation::ALL,
            &["worktree", "copy", "shared_serialized", "local"],
        );
        check_enum(CommandQueue::ALL, &["off", "fan_out_only", "always"]);
    }

    #[test]
    fn unknown_enum_text_is_rejected() {
        let err = Status::from_str("archived").expect_err("not a CHECK value");
        assert_eq!(
            err,
            ParseEnumError {
                enum_name: "Status",
                value: "archived".to_owned()
            }
        );
        assert_eq!(err.to_string(), "`archived` is not a valid Status");
        assert!(RunKind::from_str("").is_err());
    }

    #[test]
    fn status_terminality_matches_readiness_rule() {
        for status in Status::ALL {
            assert_eq!(
                status.is_terminal(),
                matches!(status, Status::Done | Status::Closed),
                "{status} terminality"
            );
        }
    }

    #[test]
    fn run_status_activity_matches_top_bar_rule() {
        for status in RunStatus::ALL {
            assert_eq!(
                status.is_active(),
                matches!(
                    status,
                    RunStatus::Queued | RunStatus::Running | RunStatus::AwaitingApproval
                ),
                "{status} activity"
            );
        }
    }

    /// Asserts a `Display` / `FromStr` / serde round-trip and that the serde form is transparent
    /// (identical to the wrapped `Uuid`).
    fn check_id<T>(id: T, inner: Uuid)
    where
        T: Copy + Debug + PartialEq + Display + FromStr + Serialize + DeserializeOwned,
        <T as FromStr>::Err: Debug,
    {
        assert_eq!(id.to_string(), inner.hyphenated().to_string());
        let parsed = T::from_str(&id.to_string()).expect("hyphenated uuid parses");
        assert_eq!(parsed, id);
        let json = serde_json::to_string(&id).expect("serialize");
        assert_eq!(json, serde_json::to_string(&inner).expect("serialize uuid"));
        let back: T = serde_json::from_str(&json).expect("deserialize");
        assert_eq!(back, id);
    }

    #[test]
    fn id_newtypes_round_trip() {
        let u = Uuid::now_v7();
        check_id(UserId::from_uuid(u), u);
        check_id(BoxId::from_uuid(u), u);
        check_id(WorkspaceId::from_uuid(u), u);
        check_id(ProjectId::from_uuid(u), u);
        check_id(RepoId::from_uuid(u), u);
        check_id(ItemKindId::from_uuid(u), u);
        check_id(ItemId::from_uuid(u), u);
        check_id(NoteId::from_uuid(u), u);
        check_id(DocumentId::from_uuid(u), u);
        check_id(StepGraphId::from_uuid(u), u);
        check_id(PhaseId::from_uuid(u), u);
        check_id(PromptTemplateId::from_uuid(u), u);
        check_id(AgentId::from_uuid(u), u);
        check_id(RunId::from_uuid(u), u);
        check_id(StepId::from_uuid(u), u);
        check_id(SkillId::from_uuid(u), u);
        check_id(SkillBindingId::from_uuid(u), u);
        check_id(CommandRunId::from_uuid(u), u);
    }

    #[test]
    fn minted_ids_are_distinct_and_v7() {
        let a = ItemId::new();
        let b = ItemId::new();
        assert_ne!(a, b, "each mint is a fresh UUID");
        assert_eq!(a.as_uuid().get_version_num(), 7, "§3: client-side UUIDv7");
        assert!(a < b, "v7 is time-ordered, so B-tree inserts stay ordered");
        assert!(ItemId::from_str("not-a-uuid").is_err());
    }

    #[test]
    fn scope_orders_project_ids_by_position() {
        let ws = WorkspaceSummary {
            workspace_id: WorkspaceId::new(),
            slug: "core".to_owned(),
            name: "Core".to_owned(),
            projects: vec![
                ProjectRef {
                    project_id: ProjectId::from_uuid(Uuid::from_u128(3)),
                    slug: "third".to_owned(),
                    name: "Third".to_owned(),
                    position: 2,
                },
                ProjectRef {
                    project_id: ProjectId::from_uuid(Uuid::from_u128(1)),
                    slug: "first".to_owned(),
                    name: "First".to_owned(),
                    position: 0,
                },
                ProjectRef {
                    project_id: ProjectId::from_uuid(Uuid::from_u128(2)),
                    slug: "second".to_owned(),
                    name: "Second".to_owned(),
                    position: 1,
                },
            ],
        };

        let scope = Scope::from_workspace(&ws);

        assert_eq!(scope.workspace_id, ws.workspace_id);
        assert_eq!(
            scope.project_ids,
            vec![
                ProjectId::from_uuid(Uuid::from_u128(1)),
                ProjectId::from_uuid(Uuid::from_u128(2)),
                ProjectId::from_uuid(Uuid::from_u128(3)),
            ]
        );
        assert!(scope.contains(ProjectId::from_uuid(Uuid::from_u128(2))));
        assert!(!scope.contains(ProjectId::new()));
        assert!(!scope.is_empty());
    }

    #[test]
    fn scope_of_an_empty_workspace_is_empty() {
        let ws = WorkspaceSummary {
            workspace_id: WorkspaceId::new(),
            slug: "empty".to_owned(),
            name: "Empty".to_owned(),
            projects: Vec::new(),
        };
        assert!(Scope::from_workspace(&ws).is_empty());
    }
}
